import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Public family counts read current top cards when drawing and never infer a family from a name. */
public final class FamilyDrawCountTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String DRAW="{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1,\"count_type\":\"POKEMON_COUNT\",\"count_target\":\"ALL_OPPONENT_POKEMON\",\"pokemon_families\":\"MEGA_EVOLUTION_EX\"}";
    static void check(boolean ok,String why){GeneratedRuleBatch8Test.check(ok,why);}
    static void atomic(ServerMatch m,Runnable r){GeneratedRuleBatch44Test.assertRejectedAtomic(m,r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static TrainerProfile trainer(){return BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"SUPPORTER\",\"effects\":["+DRAW+"]}").getAsJsonObject(),EffectRegistry.standard());}
    static class Config {String trainerId="trainer",activeId="plain",evolve;TrainerProfile trainer=trainer();CardDefinition definition;List<String> benches=List.of("mega");boolean later=true;}
    static Set<PokemonFamily> family(String id){return switch(id){case "mega","evolved_mega"->Set.of(PokemonFamily.RULE_BOX,PokemonFamily.EX,PokemonFamily.MEGA_EVOLUTION_EX);case "ex"->Set.of(PokemonFamily.RULE_BOX,PokemonFamily.EX);case "legacy"->Set.of(PokemonFamily.RULE_BOX,PokemonFamily.EX_LEGACY);case "vm"->Set.of(PokemonFamily.RULE_BOX,PokemonFamily.V,PokemonFamily.VMAX);default->Set.of();};}
    static ServerMatch game(){return game(new Config());}
    static ServerMatch game(Config c){
        var amounts=new LinkedHashMap<String,Integer>();amounts.put("plain",12);amounts.put("mega",16);for(String id:List.of("ex","legacy","vm"))amounts.put(id,6);amounts.put("evolved_mega",4);amounts.put("evolved_plain",4);amounts.put(c.trainerId,6);
        var defs=new ArrayList<CardDefinition>();var profiles=new HashMap<String,PokemonProfile>();
        for(String id:amounts.keySet()){boolean trainer=id.equals(c.trainerId),evolved=id.startsWith("evolved_");defs.add(trainer&&c.definition!=null?c.definition:new CardDefinition(id,id.equals("plain")?"Mega Forged ex":id,trainer?CardCategory.TRAINER:CardCategory.POKEMON,trainer?c.trainer.category():TrainerCategory.NONE,"J",Set.of("international"),!trainer&&!evolved,false,60,Map.of(),EffectSupport.SUPPORTED,null,family(id)));
            if(!trainer)profiles.put(id,new PokemonProfile(500,0,evolved?(id.equals("evolved_mega")?"plain":"mega"):null,null,0,null,0,1,List.of(GeneratedRuleBatch59Test.hit(EnergyType.COLORLESS,false,10)),List.of(),EnergyType.COLORLESS));}
        var catalog=new CombatCatalog(profiles,Map.of(),Map.of(c.trainerId,c.trainer));var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(var e:amounts.entrySet())for(int i=0;i<e.getValue();i++)cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),cards.size()+1),owner,e.getKey()));check(cards.size()==60,"Expected60 fixture cards");decks.add(cards);}
        for(int seed=0;seed<3000;seed++){
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(A).hand().stream().noneMatch(x->x.definitionId().equals("plain"))||m.privateView(B).hand().stream().noneMatch(x->x.definitionId().equals(c.activeId)))continue;
            m.chooseOpeningActive(A,hand(m,A,"plain").instanceId());m.chooseOpeningActive(B,hand(m,B,c.activeId).instanceId());m.startAfterOpening(A);m.startAfterOpening(B);OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);
            if(m.privateView(A).hand().stream().filter(x->x.definitionId().equals(c.trainerId)).count()<2||m.privateView(A).hand().stream().noneMatch(x->x.definitionId().equals("mega")))continue;
            var required=new HashMap<String,Integer>();for(String id:c.benches)required.merge(id,1,Integer::sum);if(c.evolve!=null)required.merge(c.evolve,1,Integer::sum);
            if(required.entrySet().stream().anyMatch(e->m.privateView(B).hand().stream().filter(x->x.definitionId().equals(e.getKey())).count()<e.getValue()))continue;
            if(c.later){m.endTurn(A);for(String id:c.benches)m.playBasicPokemonToBench(B,hand(m,B,id).instanceId());if(c.evolve!=null)m.evolveByEffect(B,active(m,B),hand(m,B,c.evolve).instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.endTurn(B);m.playBasicPokemonToBench(A,hand(m,A,"mega").instanceId());}return m;
        }throw new AssertionError("No family draw fixture");
    }
    static CardInstance play(ServerMatch m,String id){var card=hand(m,A,id);m.playTrainer(A,card.instanceId(),null);return card;}
    public static void main(String[] args){counts();mixed();topCard();authorityAndQuota();firstTurn();shortDeck();genericQueries();malformed();System.out.println("FamilyDrawCountTest passed:0..6 live opponent top-card family counts, Active/Bench and ownership, ordinary/legacyEX/VMAX/name exclusions, evolution/devolution, no-effect rejection, short deck, Supporter quota, authority/replay and strict count schema");}
    static void counts(){for(int n=0;n<=6;n++){var c=new Config();c.activeId=n==6?"mega":"plain";c.benches=Collections.nCopies(n==6?5:n,"mega");var m=game(c);var before=m.privateView(A);var opponent=m.privateView(B);var rng=m.randomTranscript();if(n==0){check(!m.canPlayTrainer(A,hand(m,A,c.trainerId).instanceId(),null),"No target family was playable");atomic(m,()->play(m,c.trainerId));continue;}var card=play(m,c.trainerId);check(m.privateView(A).hand().size()==before.hand().size()-1+n&&m.privateView(A).deck().size()==before.deck().size()-n&&m.privateView(A).discard().contains(card)&&m.privateView(B).equals(opponent)&&m.randomTranscript().equals(rng),"Family draw amount or owner wrong "+n);}}
    static void mixed(){var c=new Config();c.activeId="mega";c.benches=List.of("mega","ex","legacy","vm","plain");var m=game(c);int size=m.privateView(A).hand().size();play(m,c.trainerId);check(m.privateView(A).hand().size()==size+1,"Ordinaryex/legacyMegaEX/VMAX/name-only/own Pokemon counted");}
    static void topCard(){for(boolean promote:List.of(false,true)){var c=new Config();c.activeId=promote?"plain":"mega";c.evolve=promote?"evolved_mega":"evolved_plain";c.benches=List.of("mega");var m=game(c);int size=m.privateView(A).hand().size();play(m,c.trainerId);check(m.privateView(A).hand().size()==size+(promote?1:0),"Underlying evolution card counted instead of current top");m.endTurn(A);m.devolvePokemonToHandByEffect(B,B,active(m,B));m.endTurn(B);size=m.privateView(A).hand().size();play(m,c.trainerId);check(m.privateView(A).hand().size()==size+(promote?0:1),"Family count did not refresh after devolution");}}
    static void authorityAndQuota(){var m=game();var card=hand(m,A,"trainer");atomic(m,()->m.playTrainer(B,card.instanceId(),null));var session=MatchSession.multiplayer(m,A,B);var view=session.view(A,A);var option=view.options().stream().filter(o->o.labelZh().contains("trainer")).findFirst().orElseThrow();session.submit(A,A,view.revision(),option.index());atomic(m,()->session.submit(A,A,view.revision(),option.index()));atomic(m,()->play(m,"trainer"));check(m.currentPlayer().equals(A),"Supporter ended turn");}
    static void firstTurn(){var c=new Config();c.activeId="mega";c.later=false;var m=game(c);atomic(m,()->play(m,c.trainerId));}
    static void shortDeck(){for(int left:List.of(0,1)){var c=new Config();c.activeId="mega";c.benches=List.of("mega","mega");var m=game(c);m.discardTopDeckCardsByEffect(A,A,m.privateView(A).deck().size()-left);if(left==0){atomic(m,()->play(m,c.trainerId));continue;}int size=m.privateView(A).hand().size();play(m,c.trainerId);check(m.privateView(A).hand().size()==size&&m.privateView(A).deck().isEmpty()&&m.phase()==MatchPhase.TURN,"Short effect draw caused loss or invented cards");}}
    static void genericQueries(){for(String[] q:List.of(new String[]{"ALL_OPPONENT_POKEMON","EX|MEGA_EVOLUTION_EX","ANY","3"},new String[]{"ALL_OPPONENT_POKEMON","EX|MEGA_EVOLUTION_EX","ALL","2"},new String[]{"ALL_OPPONENT_POKEMON","MEGA_EVOLUTION_EX","NONE","4"},new String[]{"OPPONENT_BENCH","MEGA_EVOLUTION_EX","ANY","1"},new String[]{"ALL_OWN_POKEMON","MEGA_EVOLUTION_EX","ANY","1"},new String[]{"OWN_BENCH","MEGA_EVOLUTION_EX","ANY","1"})){
        var c=new Config();c.activeId="mega";c.benches=List.of("mega","ex","legacy","vm","plain");var e=JsonParser.parseString(DRAW).getAsJsonObject();e.addProperty("count_target",q[0]);e.addProperty("pokemon_families",q[1]);e.addProperty("family_match",q[2]);var data=new JsonObject();data.addProperty("trainerCategory","SUPPORTER");var effects=new JsonArray();effects.add(e);data.add("effects",effects);c.trainer=BundledCombatData.trainer(data,EffectRegistry.standard());var m=game(c);int size=m.privateView(A).hand().size();play(m,c.trainerId);check(m.privateView(A).hand().size()==size-1+Integer.parseInt(q[3]),"Generic family query changed ownership/membership "+Arrays.toString(q));
    }}
    static void malformed(){for(String raw:List.of(DRAW.replace("MEGA_EVOLUTION_EX","UNKNOWN"),DRAW.replace("ALL_OPPONENT_POKEMON","DECK"),DRAW.replace("ALL_OPPONENT_POKEMON","OPPONENT_ACTIVE"),DRAW.replace("POKEMON_COUNT","HAND_SIZE"),DRAW.replace(",\"pokemon_families\":\"MEGA_EVOLUTION_EX\"",""),DRAW.replace("\"amount\":1","\"amount\":1,\"count_offset\":0"),DRAW.replace("\"amount\":1","\"amount\":1,\"pokemon_names\":\"Mega\""))){boolean rejected=false;try{var e=EffectRegistry.standard().parse(JsonParser.parseString(raw).getAsJsonObject());EffectSchemaValidator.validate(e);}catch(IllegalArgumentException expected){rejected=true;}check(rejected,"Malformed family draw accepted: "+raw);}}
}
